const p = $('Przygotuj zapytanie').first().json;
const norm = (s) => String(s || '').toLowerCase().replace(/ł/g, 'l').normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const words = norm(p.query).split(/[^a-z0-9]+/).filter(w => w.length > 2).map(w => w.length > 5 ? w.slice(0, w.length - 2) : w);
const statusFilter = norm(p.status);
const tasks = $input.all().flatMap(i => i.json.tasks || []);
const d = (ms) => ms ? new Date(Number(ms)).toISOString().slice(0, 10) : null;
let rows = tasks.map(t => {
  const hay = norm([t.name, t.text_content || t.description || '', (t.tags || []).map(x => x.name).join(' '), (t.assignees || []).map(a => a.username).join(' ')].join(' '));
  const score = words.reduce((s, w) => s + (hay.includes(w) ? 1 : 0), 0);
  return { t, score };
});
if (words.length) rows = rows.filter(r => r.score > 0);
if (statusFilter) rows = rows.filter(r => norm(r.t.status && r.t.status.status).includes(statusFilter));
rows.sort((a, b) => b.score - a.score || Number(b.t.date_updated || 0) - Number(a.t.date_updated || 0));
const statusy = {};
for (const r of rows) { const s = (r.t.status && r.t.status.status) || 'brak'; statusy[s] = (statusy[s] || 0) + 1; }
const zadania = rows.slice(0, 15).map(r => ({
  nazwa: r.t.name,
  status: r.t.status && r.t.status.status,
  przypisani: (r.t.assignees || []).map(a => a.username).join(', ') || 'nikt',
  termin: d(r.t.due_date),
  priorytet: r.t.priority && r.t.priority.priority,
  ostatnia_zmiana: d(r.t.date_updated),
  opis: String(r.t.text_content || '').replace(/\s+/g, ' ').slice(0, 300),
  link: r.t.url
}));
return [{ json: {
  lista: 'Plan (Dział Techniczo-Montażowy)',
  zapytanie: p.query,
  liczba_pasujacych: rows.length,
  liczba_wszystkich_zadan: tasks.length,
  podsumowanie_statusow: statusy,
  zadania,
  instrukcja: 'Odpowiadaj tylko na podstawie tych zadań. Podawaj nazwę zadania, status, osobę i termin. Jeśli pasujących jest więcej niż 15, powiedz o tym i zaproponuj zawężenie. Nie czytaj linków. Jeśli nic nie pasuje, powiedz to wprost.'
} }];

// Przygotowanie nowego zadania ClickUp na podstawie danych od agenta
const TOKEN = 'pk_105689437_47ZEHB15OGJWBD0YRYIXHH6A2NY8IJ2Y';
const TEAM_ID = '90121973040';
const b = $input.first().json.body || {};
const norm = (s) => String(s || '').toLowerCase().replace(/ł/g, 'l').normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
const name = String(b.nazwa || b.name || '').trim();
const description = String(b.opis || b.description || '').trim();
const terminRaw = String(b.termin || b.due_date || '').trim();
const prioRaw = norm(b.priorytet || b.priority || '');
const osobyRaw = String(b.osoby || b.assignees || '').split(/[,;]+/).map(s => s.trim()).filter(Boolean);

if (!name) return [{ json: { ok: false, powod: 'Brak nazwy zadania. Zapytaj rozmówcę, jak ma się nazywać zadanie.' } }];

// Termin w formacie RRRR-MM-DD
let due = null;
if (terminRaw) {
  const m = terminRaw.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!m) return [{ json: { ok: false, powod: 'Termin musi mieć format RRRR-MM-DD (np. 2026-10-23). Przelicz datę podaną przez rozmówcę i spróbuj ponownie.' } }];
  due = Date.UTC(+m[1], +m[2] - 1, +m[3], 10, 0, 0);
}

// Priorytet: 1 pilny, 2 wysoki, 3 normalny, 4 niski
const prioMap = { pilny: 1, pilne: 1, urgent: 1, wysoki: 2, high: 2, normalny: 3, normal: 3, sredni: 3, niski: 4, low: 4 };
const priority = prioRaw ? (prioMap[prioRaw] || null) : null;

// Osoby: dopasowanie do członków przestrzeni ClickUp
let members = [];
try {
  const r = await this.helpers.httpRequest({ method: 'GET', url: 'https://api.clickup.com/api/v2/team', headers: { Authorization: TOKEN }, json: true, timeout: 8000 });
  const team = (r.teams || []).find(t => String(t.id) === TEAM_ID) || (r.teams || [])[0] || {};
  members = (team.members || []).map(m => m.user).filter(Boolean);
} catch (e) { members = []; }
const assignees = [];
const nieznalezieni = [];
const wieleDopasowan = [];
for (const o of osobyRaw) {
  const parts = norm(o).split(/\s+/).filter(Boolean);
  const hits = members.filter(u => {
    const hay = norm((u.username || '') + ' ' + (u.email || ''));
    return parts.every(p => hay.includes(p));
  });
  if (hits.length === 1) assignees.push({ id: hits[0].id, kto: hits[0].username });
  else if (hits.length > 1) wieleDopasowan.push(o + ' (' + hits.map(h => h.username).join(', ') + ')');
  else nieznalezieni.push(o);
}
if (wieleDopasowan.length) return [{ json: { ok: false, powod: 'Kilka osób pasuje do: ' + wieleDopasowan.join('; ') + '. Dopytaj rozmówcę o nazwisko.' } }];

const payload = { name, markdown_description: description || undefined, assignees: assignees.map(a => a.id) };
if (due) { payload.due_date = due; payload.due_date_time = false; }
if (priority) payload.priority = priority;
return [{ json: { ok: true, payload, przypisani: assignees.map(a => a.kto), nieznalezieni } }];
